  ]
}

interface Seen {
  readonly method: string
  readonly path: string
  readonly host: string
  readonly origin: string
  readonly status: number
  readonly allowOrigin: string
}

const makeHost = async (name: string, other: string) => {
  const dir = join(SCRATCH, name)
  mkdirSync(dir, { recursive: true })
  const options = {
    dir,
    timezone: "UTC",
    port: P,
    tailnetRead: "member" as const,
    tailnetWrite: "member-except-hosts" as const,
    agentHosts: [other],
    excludedDevices: [],
    name,
    peers: [{ name: other, host: other }],
  }
  const paths = FileDevices.pathsOf(dir, join(SCRATCH, `${name}-config`))
  for (const path of paths) {
    mkdirSync(join(path, ".."), { recursive: true })
    await Bun.write(path, JSON.stringify({ v: 1, agents: [{ name: other, ids: [`n-${other}`] }], excluded: [] }))
  }
  const log = FileLog.make(dir)
  await run(Effect.forEach(seedOf(name), (event) => log.append(encodeLine(event), event.t), { discard: true }))
  const members = Ref.makeUnsafe(STARTING)
  const sighting = Ref.makeUnsafe<Sighting>(UNSEEN)
  const probe = probeKeeping(writeConfigOf(options), Effect.succeed({ tailnet: noTailnet("chrome-stand-in"), status: statusOf(name, other) }), members, FileDevices.readCopies(paths), (seen) => Ref.set(sighting, seen))
  await run(probe)
  setInterval(() => void run(probe), 20_000)
  const stored: Array<string> = []
  const peers = await run(livePeers(options, sighting))
  const base = handlersOf(options, log, { question: () => Effect.die("unused"), item: () => Effect.die("unused") }, Effect.succeed("yes"), Ref.get(members), peers)
  const handlers: Listener.Handlers = {
    ...base,
    write: (line) => Effect.andThen(base.write(line), Effect.sync(() => void stored.push(`mark ${JSON.stringify(line)}`))),
    answer: (input) => Effect.as(Effect.sync(() => void stored.push(`answer ${JSON.stringify(input)}`)), AnswerOutcome.Answered({ replaced: Option.none() })),
  }
  void Effect.runFork(servePeers(peers.pull, "2 seconds"))
  const address = `${V4[name]}:${P}`
  const site: Listener.Site = { listener: "tailnet", hosts: [address], names: [`${name}.${SUFFIX}:${P}`, `${name}:${P}`], home: `http://${address}/` }
  const seen: Array<Seen> = []
  const server = Bun.serve({
    hostname: "127.0.0.1",
    port: 0,
    fetch: async (request) => {
      const each = await run(Listener.answerOf(handlers, dist, request, site, PHONE))
      seen.push({
        method: request.method,
        path: new URL(request.url).pathname,
        host: String(request.headers.get("host")),
        origin: String(request.headers.get("origin")),
        status: each.status,
        allowOrigin: String(each.headers["access-control-allow-origin"] ?? ""),
      })
      return new Response(each.body, { status: each.status, headers: each.headers })
    },
  })
  return { name, port: server.port, stored, seen, origins: await run(peers.origins), stop: () => server.stop(true) }
}

