/**
 * Bisects the hymnal port's cold launch bytes of `/` over main's first-parent
 * commits from the budget's commit to a head, in the lane: each point is
 * checked out detached, installed when bun.lock changed, built with
 * `bun run build:web`, and measured with that commit's own
 * `tools/drive-web.ts web measure --json`. A segment whose ends differ by
 * more than THRESHOLD bytes is split until each jump is one commit.
 * `bun bisect.ts <lane> <from> <to>`; rows go to points.tsv beside it,
 * each report to reports/<sha>.json. The lane is switched back to its
 * branch at the end.
 */
import { existsSync, mkdirSync, readFileSync, appendFileSync } from 'node:fs';
import { join } from 'node:path';

const [lane, from, to] = process.argv.slice(2);
if (!lane || !from || !to) throw new Error('usage: bun bisect.ts <lane> <from> <to>');
const here = import.meta.dir;
const reports = join(here, 'reports');
mkdirSync(reports, { recursive: true });
const tsv = join(here, 'points.tsv');
const THRESHOLD = 1500;
const app = join(lane, 'apps/hymnal-exact');

const sh = (cmd: Array<string>, cwd = lane) => {
  const out = Bun.spawnSync(cmd, { cwd, stdout: 'pipe', stderr: 'pipe', env: process.env });
  return { code: out.exitCode, out: out.stdout.toString(), err: out.stderr.toString() };
};

const branch = sh(['git', 'rev-parse', '--abbrev-ref', 'HEAD']).out.trim();
const list = sh([
  'git',
  'rev-list',
  '--first-parent',
  '--reverse',
  `${from}..${to}`,
  '--',
  'apps/hymnal-exact',
  'apps/hymnal',
  'packages/hymnal',
  'packages/exact-kit',
  'bun.lock',
  'package.json',
]).out.trim().split('\n');
const commits = [sh(['git', 'rev-parse', from]).out.trim(), ...list];
console.log(`${commits.length} points from ${from} to ${to}`);

let lock = '';
const cache = new Map<string, number>();
const measure = (sha: string): number => {
  const known = cache.get(sha);
  if (known !== undefined) return known;
  const file = join(reports, `${sha.slice(0, 12)}.json`);
  if (existsSync(file)) {
    const value = (JSON.parse(readFileSync(file, 'utf8')).measure?.measured?.['/ cold']?.bytes ?? -1) as number;
    cache.set(sha, value);
    return value;
  }
  const sw = sh(['git', 'switch', '--detach', sha]);
  if (sw.code !== 0) throw new Error(`switch ${sha}: ${sw.err}`);
  const nowLock = sh(['git', 'rev-parse', `${sha}:bun.lock`]).out.trim();
  if (nowLock !== lock) {
    const install = sh(['bun', 'install', '--frozen-lockfile']);
    if (install.code !== 0) console.log(`install ${sha}: ${install.err.slice(-300)}`);
    lock = nowLock;
  }
  const build = sh(['bun', 'run', 'build:web'], app);
  let value = -1;
  if (build.code === 0) {
    sh(['bun', 'tools/drive-web.ts', 'web', 'measure', '--json', file], app);
    if (existsSync(file))
      value = (JSON.parse(readFileSync(file, 'utf8')).measure?.measured?.['/ cold']?.bytes ?? -1) as number;
  } else console.log(`build ${sha}: ${(build.err + build.out).slice(-400)}`);
  const subject = sh(['git', 'log', '-1', '--format=%h %ci %s', sha]).out.trim();
  appendFileSync(tsv, `${sha.slice(0, 12)}\t${value}\t${subject}\n`);
  console.log(`${value}\t${subject}`);
  cache.set(sha, value);
  return value;
};

const STEP = 12;
const coarse: Array<number> = [];
for (let i = 0; i < commits.length; i += STEP) coarse.push(i);
if (coarse.at(-1) !== commits.length - 1) coarse.push(commits.length - 1);

const split = (lo: number, hi: number) => {
  if (hi - lo <= 1) return;
  const a = measure(commits[lo]!);
  const b = measure(commits[hi]!);
  if (Math.abs(b - a) <= THRESHOLD && a > 0 && b > 0) return;
  const mid = Math.floor((lo + hi) / 2);
  measure(commits[mid]!);
  split(lo, mid);
  split(mid, hi);
};

try {
  for (const i of coarse) measure(commits[i]!);
  for (let k = 0; k + 1 < coarse.length; k++) split(coarse[k]!, coarse[k + 1]!);
} finally {
  sh(['git', 'switch', branch]);
  sh(['bun', 'install', '--frozen-lockfile']);
  console.log(`back on ${branch}`);
}
